contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        require(address(this).balance >= value);

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        require(!c.isOperation(id));

        uint256 minDelay = c.getMinDelay();

        bool reverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(delay < minDelay && !c.isOperation(id) && c.getTimestamp(id) == 0);
        } else {
            assert(delay >= minDelay && c.isOperation(id) && c.isOperationPending(id) && c.getTimestamp(id) > 0);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        uint256 minDelay = c.getMinDelay();

        c.schedule(target, value, data, predecessor, salt, delay);

        bool scheduled = c.isOperation(id);
        bool pending = c.isOperationPending(id);
        uint256 timestamp = c.getTimestamp(id);

        assert(delay >= minDelay && scheduled && pending && timestamp > 1);
    }

    receive() external payable {}
}

